begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_column('public','nuclei','closed_at','fechamento persistido');
select has_function('public','leave_nucleus',array['uuid'],'saída autorizada pelo servidor');
select has_function('public','manage_nucleus_agreement',array['uuid','text','integer'],'gestão sem votação');
select has_column('public','nucleus_agreements','terms_version','aceite vinculado à versão');
insert into auth.users(id) values('11000000-0000-4000-8000-000000000001'),('11000000-0000-4000-8000-000000000002'),('11000000-0000-4000-8000-000000000003');
update auth.users set raw_user_meta_data='{"name":"Nome escolhido"}'::jsonb where id='11000000-0000-4000-8000-000000000002';
insert into public.nuclei(id,type,name,purpose,created_by) values('21000000-0000-4000-8000-000000000001','amigos','Administração','Convivência','11000000-0000-4000-8000-000000000001');
insert into public.nucleus_members(nucleus_id,user_id,role) values('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000001','admin'),('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002','member');
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000002',true);
select is(public.get_my_privacy_preference(),false,'ocultar autoria inicia desativado');
select is((select member->>'display_name' from jsonb_array_elements(public.get_nucleus_management('21000000-0000-4000-8000-000000000001')->'members') member where member->>'user_id'='11000000-0000-4000-8000-000000000002'),'Nome escolhido','gestão usa o nome fornecido no cadastro');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.get_nucleus_management('21000000-0000-4000-8000-000000000001')$$,'42501','not authorized','gestão não expõe participantes de núcleo alheio');
select throws_ok($$select public.get_nucleus_calendar('21000000-0000-4000-8000-000000000001',now())$$,'42501','not authorized','agenda não expõe núcleo alheio');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.update_nucleus_details('21000000-0000-4000-8000-000000000001','Novo','Propósito')$$,'42501','not authorized','membro comum não administra');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.nominate_nucleus_admin('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002')$$,'administrador nomeia');
reset role;
select is((select role from public.nucleus_members where user_id='11000000-0000-4000-8000-000000000002'),'member','nomeação não assume papel antes do aceite');
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.respond_nucleus_admin_nomination('21000000-0000-4000-8000-000000000001',true)$$,'nomeado aceita por si');
select lives_ok($$select public.update_nucleus_details('21000000-0000-4000-8000-000000000001','Novo','Propósito')$$,'novo administrador tem mesmos poderes');
select lives_ok($$select public.demote_nucleus_admin('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000001')$$,'administrador pode destituir outro');
select throws_ok($$select public.demote_nucleus_admin('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002')$$,'22023','last administrator cannot be demoted','destituição não deixa núcleo sem admin');
reset role;
create temporary table test_agreement(id uuid);
grant all on test_agreement to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000001',true);
insert into test_agreement select public.create_nucleus_agreement('21000000-0000-4000-8000-000000000001','habit','Caminhar','Cuidar juntos','Manhã','Diária',7);
select is((select count(*)::int from public.nucleus_agreement_participants where agreement_id=(select id from test_agreement)),0,'propor não aceita por ninguém');
select lives_ok($$select public.respond_nucleus_agreement((select id from test_agreement),'declined',(select terms_version from public.nucleus_agreements where id=(select id from test_agreement)))$$,'recusa individual');
select is((select status from public.nucleus_agreements where id=(select id from test_agreement)),'pending','recusa não cancela proposta geral');
select throws_ok($$select public.manage_nucleus_agreement((select id from test_agreement),'start_test',(select terms_version from public.nucleus_agreements where id=(select id from test_agreement)))$$,'42501','not authorized','membro não inicia teste');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.manage_nucleus_agreement((select id from test_agreement),'start_test',(select terms_version from public.nucleus_agreements where id=(select id from test_agreement)))$$,'admin inicia teste sem votação');
select lives_ok($$select public.respond_nucleus_agreement((select id from test_agreement),'accepted',(select terms_version from public.nucleus_agreements where id=(select id from test_agreement)))$$,'aceite individual durante teste');
select lives_ok($$select public.record_nucleus_habit_moment('21000000-0000-4000-8000-000000000001',(select id from test_agreement),'good','Memória preservada')$$,'aceite atual permite registrar');
select lives_ok($$select public.manage_nucleus_agreement((select id from test_agreement),'activate',(select terms_version from public.nucleus_agreements where id=(select id from test_agreement)))$$,'admin ativa explicitamente sem quórum');
select throws_ok($$select public.update_nucleus_agreement_terms((select id from test_agreement),'Caminhar','Cuidar juntos','Manhã','Diária',1)$$,'22023','agreement terms unchanged','salvar termos iguais não redefine consentimento');
select is((select accepted_version from public.nucleus_agreement_participants where agreement_id=(select id from test_agreement) and user_id='11000000-0000-4000-8000-000000000002'),1,'termos sem mudança conservam aceite');
select is(public.update_nucleus_agreement_terms((select id from test_agreement),'Caminhar mais','Novo combinado','Tarde','Semanal',1),2,'termos geram nova versão');
select throws_ok($$select public.respond_nucleus_agreement((select id from test_agreement),'accepted',1)$$,'40001','agreement terms changed','aceite não concorda com termos alterados após abrir página');
select is((select count(*)::int from public.nucleus_agreement_versions where agreement_id=(select id from test_agreement)),2,'versão original preservada');
select throws_ok($$select public.record_nucleus_habit_moment('21000000-0000-4000-8000-000000000001',(select id from test_agreement),'good','Sem novo aceite')$$,'42501','not authorized or current terms not accepted','versão antiga não permite gravar novos termos');
select lives_ok($$select public.respond_nucleus_agreement((select id from test_agreement),'accepted',(select terms_version from public.nucleus_agreements where id=(select id from test_agreement)))$$,'novo aceite individual');
select lives_ok($$select public.record_nucleus_habit_moment('21000000-0000-4000-8000-000000000001',(select id from test_agreement),'neutral','Nova versão')$$,'nova versão aceita permite gravar');
create temporary table test_event(id uuid);
insert into test_event select public.create_nucleus_event('21000000-0000-4000-8000-000000000001','Encontro','Convivência',now()+interval '1 day',now()+interval '1 day 1 hour','UTC');
select lives_ok($$select public.update_nucleus_event((select id from test_event),'Encontro atualizado','Convivência',now()+interval '1 day',now()+interval '1 day 1 hour','UTC')$$,'agenda funciona com papel admin');
select lives_ok($$select public.set_my_privacy_preference(true)$$,'preferência geral pode ser ativada');
select lives_ok($$select public.leave_nucleus('21000000-0000-4000-8000-000000000001')$$,'último administrador sai sem votação');
select throws_ok($$select public.get_nucleus_habit_moments((select id from test_agreement))$$,'42501','not authorized','saída revoga leitura imediatamente');
select throws_ok($$select public.respond_nucleus_agreement((select id from test_agreement),'accepted',(select terms_version from public.nucleus_agreements where id=(select id from test_agreement)))$$,'42501','not authorized','saída revoga participação');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000001',true);
select is((select role from public.nucleus_members where user_id='11000000-0000-4000-8000-000000000001'),'admin','sorteio só pode promover membro restante');
select is((select status from public.nucleus_agreements where id=(select id from test_agreement)),'active','saída não encerra acordo');
select is((select count(*)::int from public.get_nucleus_habit_moments((select id from test_agreement)) where author_id is null and authorship_hidden),2,'conteúdo preservado com autoria ocultada');
select is((select count(*)::int from public.get_nucleus_calendar('21000000-0000-4000-8000-000000000001',now()) where created_by is null and can_manage),1,'agenda oculta autor que saiu sem retirar gestão do admin atual');
select is((select count(*)::int from public.get_nucleus_calendar('21000000-0000-4000-8000-000000000001',now()) e,jsonb_array_elements(e.nucleus_event_participants) p where p->>'user_id' is null),1,'presença compartilhada também oculta pessoa que saiu');
select throws_ok($$select created_by from public.nucleus_agreements$$,'42501','permission denied for table nucleus_agreements','proposta não expõe identificador interno de autor');
select throws_ok($$select created_by from public.nucleus_events$$,'42501','permission denied for table nucleus_events','agenda bruta não contorna snapshot');
select throws_ok($$select user_id from public.nucleus_event_participants$$,'42501','permission denied for table nucleus_event_participants','presença bruta não contorna snapshot');
select throws_ok($$select author_id from public.nucleus_habit_moments$$,'42501','permission denied for table nucleus_habit_moments','consulta direta não contorna ocultação');
select ok(not has_function_privilege('authenticated','public.confirm_nucleus_habit_trial(uuid)','execute'),'confirmação coletiva antiga revogada');
select ok(not has_function_privilege('authenticated','public.apply_nucleus_habit_revision(uuid)','execute'),'revisão coletiva antiga revogada');
create temporary table test_invitation(code text);
insert into test_invitation select public.create_initial_invitation('21000000-0000-4000-8000-000000000001');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000003',true);
select lives_ok($$select public.accept_invitation((select code from test_invitation))$$,'novo participante entra por convite');
select lives_ok($$select public.respond_nucleus_agreement((select id from test_agreement),'accepted',(select terms_version from public.nucleus_agreements where id=(select id from test_agreement)))$$,'novo participante escolhe participar sem voto original');
select lives_ok($$select public.leave_nucleus('21000000-0000-4000-8000-000000000001')$$,'membro comum sai');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.set_my_privacy_preference(false)$$,'preferência pode mudar para saídas futuras');
select lives_ok($$select public.accept_invitation((select code from test_invitation))$$,'retorno autorizado por convite válido');
select is((select count(*)::int from public.get_nucleus_calendar('21000000-0000-4000-8000-000000000001',now()) e,jsonb_array_elements(e.nucleus_event_participants) p where (p->>'is_own')::boolean and p->>'user_id' is null),1,'retorno identifica própria presença sem revelar autoria aos demais');
select throws_ok($$select public.record_nucleus_habit_moment('21000000-0000-4000-8000-000000000001',(select id from test_agreement),'good','Retorno sem aceite')$$,'42501','not authorized or current terms not accepted','retorno não restaura participação sem novo aceite');
select lives_ok($$select public.respond_nucleus_agreement((select id from test_agreement),'accepted',2)$$,'retorno permite novo aceite explícito');
select lives_ok($$select public.record_nucleus_habit_moment('21000000-0000-4000-8000-000000000001',(select id from test_agreement),'good','Novo registro identificado')$$,'registro posterior ao retorno tem preferência própria');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.remove_nucleus_member('21000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002')$$,'admin remove participante');
select is((select count(*)::int from public.get_nucleus_habit_moments((select id from test_agreement)) where author_id is null),2,'retorno não reidentifica autoria anteriormente ocultada');
select is((select count(*)::int from public.get_nucleus_habit_moments((select id from test_agreement)) where author_id='11000000-0000-4000-8000-000000000002'),1,'saída futura com opção desligada mantém novo registro identificado');
select is((public.leave_nucleus('21000000-0000-4000-8000-000000000001')->>'closed')::boolean,true,'último membro fecha núcleo');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.accept_invitation((select code from test_invitation))$$,'P0002','invitation unavailable','convite antigo não reabre núcleo');
reset role;
select is((select count(*)::int from public.nucleus_habit_moments where agreement_id=(select id from test_agreement)),3,'fechamento preserva momentos');
select ok((select closed_at is not null from public.nuclei where id='21000000-0000-4000-8000-000000000001'),'fechamento registrado');
select is((select count(*)::int from public.nucleus_invitations where nucleus_id='21000000-0000-4000-8000-000000000001' and revoked_at is null),0,'fechamento revoga todos os convites');
select ok(not has_function_privilege('anon','public.leave_nucleus(uuid)','execute'),'anônimo não sai em nome de usuário');
select ok(not has_function_privilege('authenticated','public.depart_nucleus_member(uuid,uuid)','execute'),'helper interno não permite remover pessoas sem gestão');
select ok(not has_function_privilege('authenticated','public.respond_nucleus_agreement(uuid,text)','execute'),'aceite antigo sem versão não pode contornar confirmação dos termos');
select ok(not has_function_privilege('authenticated','public.get_nucleus_habit_trial_state(uuid)','execute'),'helper de votação legado não revela identidade de autores');
select * from finish();
rollback;
